def transform(grid):
    # Repeat each colored motif periodically across the rectangular zero canvas
    import collections
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    seen=set()
    for r in range(h):
      for c in range(w):
        col=grid[r][c]
        if col in (0,8) or (r,c) in seen: continue
        pts=[]; q=[(r,c)]; seen.add((r,c))
        while q:
          y,x=q.pop(); pts.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<h and 0<=xx<w and grid[yy][xx]==col and (yy,xx) not in seen:
              seen.add((yy,xx)); q.append((yy,xx))
        # Motif within its minimal bounding rectangle
        r0=min(y for y,x in pts); r1=max(y for y,x in pts); c0=min(x for y,x in pts); c1=max(x for y,x in pts)
        th,tw=r1-r0+1,c1-c0+1
        # Identify contiguous zero rectangle containing motif
        # handle canvas as all zeros in nearby rectangular area
        zeros=[(y,x) for y in range(r0-1,r1+10) for x in range(c0-1,c1+10) if 0<=y<h and 0<=x<w and grid[y][x]==0]
        if not zeros: continue
        # flood zero cells adjacent (8-connected) to motif perimeter
        region=set(); stack=[]
        for y,x in pts:
          for dy in (-1,0,1):
            for dx in (-1,0,1):
              yy,xx=y+dy,x+dx
              if 0<=yy<h and 0<=xx<w and grid[yy][xx]==0: stack.append((yy,xx))
        while stack:
          y,x=stack.pop()
          if (y,x) in region or grid[y][x]!=0: continue
          region.add((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<h and 0<=xx<w: stack.append((yy,xx))
        if not region: continue
        a=min(y for y,x in region); b=max(y for y,x in region); l=min(x for y,x in region); rr=max(x for y,x in region)
        # repeat motif in its zero canvas and preserve seed motif
        for y in range(a,b+1):
          for x in range(l,rr+1):
            if grid[y][x]==0 and grid[r0+(y-r0)%th][c0+(x-c0)%tw]==col:
              out[y][x]=col
    return out
